const p1 = h2.list({ tenant: 'a', limit: 2 });
assert.deepEqual(p1.items.map(x => x.id), ['a', 'b']);
assert.equal(p1.nextCursor, '2026-01-01|b');
const p2 = h2.list({ tenant: 'a', limit: 2, cursor: p1.nextCursor });
assert.deepEqual(p2.items.map(x => x.id), ['c']);
assert.equal(p2.nextCursor, null);
assert.deepEqual(h2.list({ tenant: 'a', limit: 5, cursor: '2026-01-01|m' }).items.map(x => x.id), ['b', 'c']);
for (const cursor of ['', 'x', '|a', 'a|', 'a|b|c']) assert.throws(() => h2.list({ tenant: 'a', limit: 1, cursor }), /invalid request/);
